<div class="d-flex justify-content-between align-items-center mb-3"><h1>Cadastro de produtos</h1><a class="btn btn-primary" href="/?r=produtos&form=1">Novo produto</a></div>
<form class="row g-2 mb-3"><input type="hidden" name="r" value="produtos"><div class="col-md-9"><input class="form-control" name="q" placeholder="Buscar por nome ou código" value="<?=htmlspecialchars($_GET['q']??'')?>"></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Buscar</button></div></form>
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Estoque</th><th>Preço unitário</th><th>Ações</th></tr></thead><tbody>
<?php foreach($produtos as $p): ?><tr><td><?=htmlspecialchars($p['cod'])?></td><td><?=htmlspecialchars($p['nome'])?></td><td><?=htmlspecialchars($p['categoria']??'')?></td><td><?=$p['quantidade']?></td><td>R$ <?=number_format((float)$p['preco_unitario'],2,',','.')?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-warning" href="/?r=produtos&form=1&id=<?=$p['id']?>">Editar</a><form method="post" action="/?r=produtos" onsubmit="return confirm('Excluir este produto?')"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-danger" name="excluir">Excluir</button></form></td></tr><?php endforeach; ?>
<?php if(!$produtos): ?><tr><td colspan="6">Nenhum produto cadastrado.</td></tr><?php endif; ?></tbody></table></div>
